let w,state,lastTrigger;
const iconPaths={controls:'M4 5H20 M4 12H20 M4 19H20 M9 2V8 M15 9V15 M8 16V22',plot:'M3 3V21H21 M6 17Q11 16 13 11T21 5',evidence:'M5 3H15L20 8V21H5Z M15 3V8H20 M8 12H17 M8 16H17',link:'M9 8H6A4 4 0 0 0 6 16H9 M15 8H18A4 4 0 0 1 18 16H15 M8 12H16',bulb:'M8 17C8 14 5 13 5 9A7 7 0 0 1 19 9C19 13 16 14 16 17Z M8 20H16 M10 23H14'};
