function makeShare(host,s,metric,title,totalUnit){
 const key=metric==='count'?'dam_count_share':'capacity_share',total=metric==='count'?s.total_dams:s.total_capacity_ml;
 const f=el('figure','sp316-share'),caption=el('figcaption','sp316-vcaption');
 caption.append(el('strong','',title),el('span','',total===null?'Incomplete records':fmt(total)+' '+totalUnit));
 if(total===null||s.rows.some(r=>r[key]===null)){
  const gap=el('div','sp316-share-missing','Incomplete capacity records');gap.setAttribute('role','note');
  gap.title='Missing capacities are left blank—not estimated. See individual records.';f.append(gap,caption);host.append(f);return;
 }
 const track=el('div','sp316-share-track');track.dataset.orientation='vertical';
 for(const g of groups){const r=s.rows.find(x=>x.group_id===g.id);if(!r)continue;
  const perc=Math.round(r[key]*100),n=metric==='count'?r.derived_count:r.derived_capacity_ml;
  const b=button(perc+'%',()=>selectGroup(g.id));groupAttrs(b,g);
  b.style.height=(r[key]*100)+'%';b.dataset.evidenceMetric=key;b.dataset.evidenceValue=r[key];
  b.setAttribute('aria-label',`${g.label}: ${perc}% of ${title.toLowerCase()}. ${r.derived_from_rounded_shares?'Approximately ':''}${fmt(n)} ${totalUnit}. Highlight ${g.label}.`);
  b.title=b.getAttribute('aria-label');track.append(b);
 }
 f.append(track,caption);host.append(f);
}
