 section.append(h,el('p','sp316-vunit','Share of each total (%)'));
 const plot=el('div','sp316-share-columns');plot.dataset.scaleMax='100';plot.append(yTicks(100,'%'));
 makeShare(plot,s,'count','Dam numbers','dams');makeShare(plot,s,'capacity','Capacity','ML');section.append(plot);const means=el('div','sp316-mean-labels');for(const g of groups){const r=s.rows.find(x=>x.group_id===g.id);if(!r)continue;const row=el('div');row.append(marker(g),el('span','',(r.derived_from_rounded_shares?'≈':'')+fmt(r.derived_count)+' dams'+(r.derived_mean_ml!==null?' · mean ≈'+fmt(r.derived_mean_ml)+' ML':'')));means.append(row);}section.append(means);
