    series.forEach((item,si)=>{const st=rainStyle(item.key),pts=[];months.forEach((m,i)=>{if(Number.isInteger(reveal)&&reveal>=-1&&i>reveal)return;const x=left+i*(plotW/(months.length-1)),v=Number(item.data[i])||0,y=top+plotH*(1-v/maxV);pts.push([x,y,i]);});if(pts.length){const dash=st.dash?` stroke-dasharray="${st.dash}"`:'';out+=`<polyline data-rainfall-setting="${item.key}" fill="none" stroke="${st.lineColor}" stroke-width="${st.strokeWidth+(.35)}"${dash} stroke-linejoin="round" stroke-linecap="round" points="${pts.map(p=>`${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ')}"/>`;pts.forEach(([x,y,i])=>{if(i===active||i===pts[pts.length-1][2])out+=rainMarker(x,y,st,2.7);});}});
