  function initWaterBalanceCarousel(root,prefix,labels){
    const prev=root.querySelector(`#${prefix}-waterBalancePrev`);
    const next=root.querySelector(`#${prefix}-waterBalanceNext`);
    const label=root.querySelector(`#${prefix}-waterBalanceMetricLabel`);
    const slides=Array.from(root.querySelectorAll('.water-balance-slide'));
    if(!prev||!next||!label||slides.length<2){return()=>{};}
    let index=0;
    const apply=()=>{slides.forEach((slide,i)=>slide.classList.toggle('is-active',i===index));label.textContent=labels[index]||'';};
    prev.addEventListener('click',()=>{index=(index-1+slides.length)%slides.length;apply();});
    next.addEventListener('click',()=>{index=(index+1)%slides.length;apply();});
    apply();
    return ()=>{index=0;apply();};
  }

