    totalCapturedML: dam.totalCapturedML,
    totalSpillML: dam.totalSpillML,
    totalOutletEffectML: dam.totalOutletEffectML,
    totalEvaporationML: dam.totalEvaporationML,
    maxStorageFraction: Math.max(...dam.storageFractions),
    endingStorageFraction: dam.endingStorageFrac,
    localDamInflowML: dam.localDamInflowML,
    localDamSpillML: dam.localDamSpillML,
