window.getScreen2WaterBalanceQASnapshot = () => {
  const dam = computeHydrology().dam;
  const plot = window.__screen2WaterBalancePlotState || null;
  return {
    qaStep: "7h-no-rainfall-accordion-final-qa",
    plot,
    checks: {
      storageSeriesLength: (dam.storageFractions || []).length,
      evaporationSeriesLength: (dam.evaporationLossML || []).length,
      monthCount: MONTHS.length,
      annualEvaporationFinite: Number.isFinite(dam.totalEvaporationML),
      reachedFullDuringSeason: Boolean(dam.reachedFullDuringSeason),
      maxPreEvapStorageFraction: dam.maxPreEvapStorageFraction,
      usesIllustrativeML: true,
      directRainfallOnDamIncluded: Boolean(dam.modelNotes?.directRainfallOnDamIncluded),
      allocationOrTakeIncluded: Boolean(dam.modelNotes?.allocationOrTakeIncluded),
      multipleDamsIncluded: Boolean(dam.modelNotes?.multipleDamsIncluded)
    }
  };
};
window.getScreen2ModelSnapshot = () => window.__screen2ControlState || getControlStateSnapshot();
window.getScreen2Phase8BOutputSnapshot = () => phase8bOutput?.getLatest() || null;

syncControlsFromState();
setupTakeawayAccordion();
const resetS2WaterBalanceCarousel=initWaterBalanceCarousel(root,'s2',['Storage after take','Total farm dam evaporation']);

// Cross-screen rainfall comparison v0.3 · Screen 2.
state.compareRainfall=false;state.comparisonReference='current';
const compareRainfallToggle=document.getElementById('compareRainfallToggle');
const compareReferenceSelect=document.getElementById('compareReferenceSelect');
function s2SelectedInfo(){return rainSelectedInfo(state,rainfallDefaults);}
function s2ModelForRainfall(info){const old={timing:state.timing,volume:state.volume,rainfallScenario:state.rainfallScenario};state.timing=info.timing;state.volume=info.volume;state.rainfallScenario=info.key;const model=computeHydrology();Object.assign(state,old);return model;}
function s2Comparison(selected){if(!state.compareRainfall)return null;const key=rainReferenceKey(selected.key,state),info=rainPresetInfo(key,rainfallDefaults);return {...info,model:s2ModelForRainfall(info)};}
