    function s3AnnualRows(series){const chip=document.getElementById('annualEvapChip');if(!chip)return;chip.classList.toggle('rainfall-annual-comparison',series.length>1);if(series.length===1){chip.innerHTML=`<span class="water-balance-annual-label">Illustrative annual farm dam evaporation</span><span class="water-balance-annual-value" id="s3-annualEvapValue">${formatApprox(series[0].data.annualEvaporationML,'ML')}</span>`;return;}chip.innerHTML=series.map(item=>{const c=item.key==='current'?' current':item.key==='custom'?' custom':'';return `<div class="rainfall-annual-row"><span class="rainfall-signature-swatch${c}"></span><span>${item.label}${item.isSelected?' · selected':''}</span><strong>${formatApprox(item.data.annualEvaporationML,'ML')}</strong></div>`;}).join('');}
