    const s4SetControlsDisabled=setControlsDisabled;setControlsDisabled=function(disabled){s4SetControlsDisabled(disabled);if(compareRainfallToggle)compareRainfallToggle.disabled=disabled;if(compareReferenceSelect)compareReferenceSelect.disabled=disabled||document.getElementById('customReferenceRow')?.hidden;};

