    function setFill(rect,fraction){if(!rect)return;const f=clamp(Number(fraction)||0,0,1);if(rect.dataset.fillMode==="radial"){const cx=Number(rect.dataset.cx),cy=Number(rect.dataset.cy),rxMax=Number(rect.dataset.rxMax),ryMax=Number(rect.dataset.ryMax),scale=Math.sqrt(f);rect.setAttribute("cx",cx.toFixed(1));rect.setAttribute("cy",cy.toFixed(1));rect.setAttribute("rx",(rxMax*scale).toFixed(1));rect.setAttribute("ry",(ryMax*scale).toFixed(1));rect.dataset.fraction=f.toFixed(3);return;}const top=Number(rect.dataset.top),bottom=Number(rect.dataset.bottom),h=(bottom-top)*f,y=bottom-h;rect.setAttribute("y",y.toFixed(1));rect.setAttribute("height",h.toFixed(1));rect.dataset.fraction=f.toFixed(3);}
