        const rawPoolEnd=poolStart+poolInflow-poolLoss;
        const poolOverflow=Math.max(0,rawPoolEnd-POOL_MODEL.maximumLevel);
        const poolMinimumSupport=Math.max(0,POOL_MODEL.minimumLevel-rawPoolEnd);
        pool=clamp(rawPoolEnd,POOL_MODEL.minimumLevel,POOL_MODEL.maximumLevel);
