/* SP3.9: local help behaviour only. No writes to model or animation state. */
(function(){
 'use strict';
 function init(){
  const helps=[...document.querySelectorAll('[data-sp39-explore] .sp39-help')];
  const close=(d,restore=false)=>{d.open=false;d.querySelector('summary').setAttribute('aria-expanded','false');if(restore)d.querySelector('summary').focus({preventScroll:true});};
  const position=d=>{
   const s=d.querySelector('summary').getBoundingClientRect(),note=d.querySelector('.sp39-help-note');
   const w=Math.min(300,innerWidth-24);note.style.width=w+'px';
   note.style.left=Math.max(12,Math.min(s.left,innerWidth-w-12))+'px';
   const h=note.getBoundingClientRect().height;
   note.style.top=(s.bottom+7+h>innerHeight-12?Math.max(12,s.top-h-7):s.bottom+7)+'px';
  };
  helps.forEach(d=>{
   const s=d.querySelector('summary');
   d.addEventListener('toggle',()=>{s.setAttribute('aria-expanded',String(d.open));if(d.open){helps.filter(x=>x!==d&&x.open).forEach(x=>close(x));position(d);}});
   d.addEventListener('keydown',e=>{if(e.key==='Escape'&&d.open){e.preventDefault();e.stopPropagation();close(d,true);}});
   d.addEventListener('focusout',()=>setTimeout(()=>{if(d.open&&!d.contains(document.activeElement))close(d);},0));
  });
  document.addEventListener('pointerdown',e=>helps.filter(d=>d.open&&!d.contains(e.target)).forEach(d=>close(d)));
  document.addEventListener('keydown',e=>{if(e.key==='Escape')helps.filter(d=>d.open).forEach(d=>close(d,true));});
  window.addEventListener('resize',()=>helps.filter(d=>d.open).forEach(position));
  window.addEventListener('scroll',()=>helps.filter(d=>d.open).forEach(position),true);
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();


