/* SP3.10: presentation-only status visibility. Keep each original run handler. */
(function(){
 'use strict';
 function init(){
  document.querySelectorAll('.sp310-run-action').forEach(action=>{
   const button=action.querySelector('.run-btn');
   if(!button)return;
   const update=()=>{action.dataset.running=String(button.textContent.trim().startsWith('Running'));};
   new MutationObserver(update).observe(button,{childList:true,subtree:true,characterData:true});
   update();
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();


