/* SP3.15 navigation/orientation only. Never writes to hydrology or evidence. */
(function(){'use strict';
 function navigate(screen,tab){
  const shell=window.Phase3ConfigurableShell;if(!shell)return;
  shell.activate(screen);shell.setLocalTab(screen,tab);
  const target=document.querySelector('#p3-'+screen+'-view-'+tab+' h2, #p3-'+screen+'-view-'+tab+' h3')||document.getElementById('p3-'+screen+'-tab-'+tab);
  if(target){if(!target.hasAttribute('tabindex'))target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}
  document.getElementById('p3-panel-'+screen)?.scrollIntoView({block:'start',behavior:'instant'});
 }
 function init(){
  document.querySelectorAll('[data-sp15-explore]').forEach(b=>b.addEventListener('click',()=>{b.closest('details').open=false;navigate(b.dataset.sp15Explore,'explore');}));
  document.querySelectorAll('[data-sp15-route]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.sp15Route,b.dataset.sp15Tab)));
  document.querySelectorAll('.sp15-connection').forEach(d=>{
   const summary=d.querySelector('summary');summary.setAttribute('aria-expanded',String(d.open));
   d.addEventListener('toggle',()=>{summary.setAttribute('aria-expanded',String(d.open));if(d.open)window.SP315Mechanism?.pause();});
   d.addEventListener('keydown',e=>{if(e.key==='Escape'){d.open=false;summary.focus();e.stopPropagation();}});
  });
  document.addEventListener('pointerdown',e=>document.querySelectorAll('.sp15-connection[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;}));
  // Opening the optional sources pauses S4 playback without changing any values.
  document.querySelectorAll('[data-sp315-sources]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)window.SP315Mechanism?.pause();}));
  window.SP315ScienceDesign=Object.freeze({version:'SP3.15',navigate});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();


