v.receiverControls=el('div','sp317-receiver-controls');const ri=el('input');ri.type='range';ri.id='sp317-receiver';ri.min=0;ri.max=100;ri.step=5;ri.value=s.receiverFraction*100;v.receiverControls.append(controlLabel('Downstream dam starts…',ri,'This receiving dam has no bypass. Water fills its available space; any excess passes onward. Change its opening storage while the upstream event stays the same.'));v.receiverValue=el('output','sp317-output');v.receiverControls.append(v.receiverValue,ri);const re=el('div','sp317-ends');re.append(el('span','','Empty'),el('span','','Full'));v.receiverControls.append(re);ri.addEventListener('input',()=>{s.receiverFraction=+ri.value/100;render6();});v.receiverInput=ri;v.controls.append(v.receiverControls,button('Reset example',()=>{Object.assign(s,cfg.event.defaults);i.value=s.flow;bi.checked=s.bypass;fi.checked=s.follow;ri.value=s.receiverFraction*100;render6();},'sp317-reset'));
v.pair=el('div','sp317-pair');v.firstFig=el('figure');v.firstFig.append(el('figcaption','','Upstream farm dam'));v.first=el('div','sp317-bucket');v.firstFig.append(v.first);v.receiverFig=el('figure');v.receiverFig.append(el('figcaption','','Downstream dam · no bypass'));v.receiver=el('div','sp317-bucket');v.receiverFig.append(v.receiver);v.pair.append(v.firstFig,v.receiverFig);v.main.append(v.pair);const note=el('div','sp317-caption');note.append(el('span','','One short event · water level after the event'),help('this short example','The same incoming flow lasts for one fixed example duration. No take, evaporation, seepage or travel losses are included during this short event. These processes still matter over longer periods.'));v.main.append(note);
