const time=el('div','sp317-time');const playgroup=el('div','sp317-play');const back=button('‹',()=>setMonth((s.month+11)%12));back.setAttribute('aria-label','Previous month');v.play=button('Play',()=>{if(timer)pause();else{if(s.month===11)s.month=0;s.playing=true;render7();timer=setInterval(()=>{if(s.month===11){pause();return;}s.month++;render7();},root.__MS_QA_FAST__?100:1200);}});v.play.setAttribute('aria-label','Play forward through the months');const next=button('›',()=>setMonth((s.month+1)%12));next.setAttribute('aria-label','Next month');playgroup.append(back,v.play,next);v.monthButtons=[];const mg=el('div','sp317-months');mg.setAttribute('role','group');mg.setAttribute('aria-label','Display month for both examples');months.forEach((m,i)=>{const b=button(m,()=>setMonth(i));b.dataset.month=i;v.monthButtons.push(b);mg.append(b);});time.append(playgroup,mg);v.main.append(time);
