function setMonth(m){pause();states[7].month=m;render7();}
function pause(){if(timer){clearInterval(timer);timer=null;}if(states[7])states[7].playing=false;if(views[7]){views[7].play.textContent='Play';views[7].play.setAttribute('aria-label','Play forward through the months');}}
function seasonalRows(){const s=states[7],sc=s.bypass?'all-bypasses':'licensed-only';return ['historic','current'].map(key=>M.simulate({key,...M.presets[key]},sc));}
function render7(){const v=views[7],s=states[7];if(!v)return;const ms=seasonalRows();s.models=ms;v.monthButtons.forEach((b,i)=>b.setAttribute('aria-pressed',i===s.month));Object.entries(v.stateButtons).forEach(([k,b])=>b.setAttribute('aria-pressed',k===s.waterState));v.play.textContent=s.playing?'Pause':'Play';v.play.setAttribute('aria-label',s.playing?'Pause month playback':'Play forward through the months');v.caption.textContent=`${months[s.month]} · Arrows: this month · Water: month ${s.waterState}`;
const rec=ms.map(m=>m.records[s.month].damRecords[cfg.seasonal.damIndex]);rec.forEach((r,i)=>D.render(v.buckets[i],{opening:r.storageStart,closing:r.storageEnd,capacity:M.dams[2].capacity,incoming:r.incomingTotal,into:r.inflowToDam,bypassed:r.bypassFlow,bypass:r.bypassActive,captured:r.captured,spill:r.spill,passed:r.outTotal,loss:r.actualStorageLoss,balanceResidual:r.storageStart+r.incomingTotal-r.outTotal-r.actualStorageLoss-r.storageEnd},{id:'sp317-season-'+i,seasonal:true,waterState:s.waterState,compare:i===1,title:M.presets[i?'current':'historic'].label+' at the downstream dam'}));D.timeline(v.timeline,ms,s.month,setMonth);
const [a,b]=rec;let message;
if(a.incomingTotal+b.incomingTotal<1e-5)message='There is almost no water arriving this month. A bypass cannot create runoff.';
else if(s.bypass)message='A bypass passes available low flows even when the dam has empty space. Higher flows can still enter storage.';
else if(Math.abs(a.captured-b.captured)>1e-5)message='Different inflow and water already stored change how much this same dam captures.';
else message='Water left after one month affects the space available for later runoff.';
v.notice.textContent=message;v.w.dataset.ready='true';}
