const d=cfg.evidence.find(d=>d.dataset_id===s.dataset)||cfg.evidence[0];s.dataset=d.dataset_id;const complete=d.years.filter(y=>y.complete);if(!d.years.some(y=>y.year===s.year))s.year=(complete.at(-1)||d.years.at(-1)).year;
