  document.querySelector('[data-sp321-pulse-help]')?.addEventListener('click',e=>{trigger=e.currentTarget;dialog.showModal();dialog.querySelector('button').focus();});
  dialog.querySelector('button').addEventListener('click',()=>dialog.close());
