/* SP3.22 Home/About guide navigation. No writes to models, evidence or screen inputs. */
(function(){
 'use strict';
 function init(){
  const root=document.querySelector('[data-sp318-page="home"]');
  const about=root?.querySelector('[data-sp322-guide]');
  if(!about||document.documentElement.dataset.sp322Ready==='true')return;
  const orientation=window.SP318Orientation;
  if(!orientation)throw new Error('SP3.22 guide requires the existing orientation navigation.');
  const title=about.querySelector('#ha-guide-title');
  const summary=about.querySelector(':scope > summary');
  const entry=root.querySelector('[data-ha-open]');
  function focusAt(element){
   if(!element)return;
   if(!element.matches('a,button,summary,input,[tabindex]'))element.tabIndex=-1;
   element.focus({preventScroll:true});
   element.scrollIntoView({block:'start',behavior:'instant'});
  }
  function sync(){
   const expanded=String(about.open);
   summary.setAttribute('aria-expanded',expanded);
   entry?.setAttribute('aria-expanded',expanded);
  }
  function openGuide(){
   orientation.navigate('home','explore',{focus:false});
   about.open=true;sync();requestAnimationFrame(()=>focusAt(title));
  }
  function closeGuide(){about.open=false;sync();focusAt(summary);}
  root.addEventListener('click',function(event){
   if(!(event.target instanceof Element)||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
   const link=event.target.closest('[data-ha-open],[data-ha-jump],[data-ha-close]');
   if(!link||!root.contains(link))return;
   event.preventDefault();
   if(link.hasAttribute('data-ha-open'))openGuide();
   else if(link.hasAttribute('data-ha-close'))closeGuide();
   else focusAt(document.getElementById(link.dataset.haJump));
  });
  about.addEventListener('toggle',sync);
  about.addEventListener('keydown',event=>{
   if(event.key==='Escape'&&event.target===summary){event.preventDefault();closeGuide();}
  });
  sync();
  document.documentElement.dataset.sp322Ready='true';
  window.SP322HomeGuide=Object.freeze({version:'SP3.22',openGuide,closeGuide,snapshot:()=>({
   open:about.open,selectedTopics:[...about.querySelectorAll('[data-ha-topic]')].map(e=>e.dataset.haTopic),
   exampleScreen:about.dataset.haExample||null,evidenceMode:about.dataset.haEvidenceMode
  })});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();



