/* SP3.22-P2 publication notices only. No writes to models, scientific review or evidence values. */
(function(){'use strict';
 const policy=window.__PUBLIC_EVIDENCE_POLICY__;if(!policy)return;
 const el=(tag,text,cls='')=>{const n=document.createElement(tag);n.className=cls;n.textContent=text;return n;};
 function note(host,id,label,text,hidden=false){
  if(!host)return;let n=host.querySelector(':scope > [data-public-notice="'+id+'"]');
  if(!n){n=el('p','','public-data-status');n.dataset.publicNotice=id;n.setAttribute('role','note');n.append(el('strong',label+' —'),document.createTextNode(text));host.prepend(n);}
  if(n.hidden!==hidden)n.hidden=hidden;
 }
 function refresh(){
  const s1=document.querySelector('#p3-S1-view-science');
  note(s1?.querySelector('[data-sp3-model-layout]'),'annual','Not final','Prepared rainfall–runoff observations retain approximate rainfall/gauge pairing, area and quality-review caveats. They are not an approved fit to this curve.',!s1?.querySelector('[data-sp3-show-data]')?.checked);
  const s3=document.querySelector('#p3-S3-view-science');
  note(s3?.querySelector('.sp311-evidence-column'),'dams','Not final','Historical survey and prepared reference extracts. The 1998 survey is a sample, not a complete present-day inventory.',!s3?.querySelector('[data-sp311-show]')?.checked);
  note(document.querySelector('#p3-S4-view-science [data-records] > div'),'take','Preliminary','Information Pack summaries: historical use and allocation periods differ; the complete original numerical table has not been independently rechecked.');
  note(document.querySelector('#p3-S5-view-science [data-evidence-body]'),'groups','Preliminary','Information Pack dam counts, capacity shares and water-use summaries. Keep the stated dates; reported use and modelled stock/domestic estimates are different evidence types.');
  const ev=document.querySelector('#p3-S7-view-science [data-local-evidence]');
  note(ev?.querySelector(':scope > div'),'flow','Not final','Prepared gauge records; hydrological quality review is outstanding. Gaps remain missing, not zero. These observations do not isolate bypass effects.');
  for(const n of document.querySelectorAll('.sp181-local-block')){
   if(n.querySelector('[data-fact-id="FACT_004"],[data-fact-id="FACT_005"],[data-fact-id="FACT_006"],[data-fact-id="FACT_007"],[data-fact-id="FACT_015"],[data-fact-id="FACT_018"]'))note(n,'context','Preliminary','Historical Information Pack extract; retain its source date, not a current inventory or current allocation rule.');
  }
  document.documentElement.dataset.publicEdition=policy.edition;
 }
 function init(){let queued=false;const observer=new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(()=>{queued=false;refresh();});}});observer.observe(document.querySelector('.phase3-stage')||document.body,{childList:true,subtree:true});document.addEventListener('change',()=>requestAnimationFrame(refresh));refresh();window.PublicEdition=Object.freeze({edition:policy.edition,refresh});}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
